      line-height: 1.12;
      letter-spacing: -0.04em;
    }

    .tagline {
      margin: 0.75rem 0 0;
      color: var(--secondary);
      max-width: 44rem;
    }

    .header-tools {
      display: flex;
      align-items: center;
      gap: 1.25rem;
      flex-shrink: 0;
    }

    .site-nav {
      display: flex;
      gap: 1rem;
      align-items: center;
    }

    .site-nav a {
      font-size: 0.95rem;
      font-weight: 650;
      text-decoration: none;
    }

    #theme-toggle {
      border: 1px solid var(--line);
      background: var(--card);
      color: var(--text);
      border-radius: 999px;
      min-width: 2.75rem;
