      padding: 0.45rem 0.7rem;
      font: inherit;
      font-size: 1.25rem;
      line-height: 1;
      cursor: pointer;
      box-shadow: var(--shadow);
    }

    main {
      max-width: 70rem;
      margin: 0 auto;
      padding: 3.5rem 1.5rem 4rem;
    }

    section + section {
      margin-top: 5rem;
    }

    .eyebrow {
      margin: 0 0 0.5rem;
      color: var(--accent);
      font-size: 0.85rem;
      font-weight: 750;
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }

    h2 {
      margin: 0;
      font-size: 1.75rem;
      line-height: 1.2;
      letter-spacing: -0.025em;
    }

    .section-intro {
      max-width: 48rem;
      margin: 0.75rem 0 2rem;
      color: var(--secondary);
    }

    .team-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(16rem, 1fr));
      gap: 1.5rem;
    }

    .member-card {
      min-width: 0;
      display: flex;
      flex-direction: column;
      align-items: flex-start;
      padding: 1.5rem;
      border: 1px solid var(--line);
      border-radius: var(--radius);
      background: var(--card);
      box-shadow: var(--shadow);
    }

    .member-card img {
      width: 8rem;
      height: 8rem;
      object-fit: cover;
      border-radius: 50%;
      border: 0.2rem solid var(--bg);
      margin-bottom: 1rem;
    }

    .member-card h3 {
      margin: 0;
      font-size: 1.25rem;
      line-height: 1.3;
    }

    .study {
      margin: 0.3rem 0 1rem;
      color: var(--secondary);
      font-size: 0.95rem;
    }

    .bio {
      margin: 0;
    }

    .fun-fact {
      margin: 0.8rem 0 1.25rem;
      color: var(--secondary);
    }

    .hot-take {
      margin: auto 0 0;
      padding: 0.65rem 0.85rem;
      border-radius: 0.8rem;
      background: var(--accent);
      color: #FFFFFF;
      font-size: 0.9rem;
      font-weight: 700;
    }

    .future-intro {
      max-width: 52rem;
      margin: 0.75rem 0 2rem;
      color: var(--secondary);
    }

    .future-panel {
      padding: 1.5rem;
      border: 1px solid var(--line);
      border-radius: var(--radius);
      background: var(--card);
      box-shadow: var(--shadow);
    }

    .future-panel h3 {
      margin: 0 0 0.75rem;
      font-size: 1.25rem;
    }

    .shared-points {
      margin: 0;
      padding-left: 1.4rem;
    }

    .shared-points li + li {
      margin-top: 0.65rem;
    }

    .outlook {
      margin: 1.5rem 0 0;
      padding: 1rem 1.1rem;
      border-left: 0.25rem solid var(--accent);
      border-radius: 0.4rem;
      background: var(--soft);
    }

    .outlook strong {
      display: block;
      margin-bottom: 0.35rem;
    }

    .tension {
      margin-top: 1.5rem;
      padding-top: 1.25rem;
      border-top: 1px solid var(--line);
    }

    .tension p {
      margin: 0.5rem 0 0;
      color: var(--secondary);
    }

    footer {
      padding: 1.5rem 1rem 2rem;
      border-top: 1px solid var(--line);
      color: var(--secondary);
      text-align: center;
      font-size: 0.8rem;
    }

    footer p {
      margin: 0;
    }

    @media (max-width: 700px) {
      .site-header {
        padding: 1.5rem 1rem;
      }

      .header-inner {
        flex-direction: column;
        align-items: stretch;
        gap: 1rem;
      }

      .header-tools {
        justify-content: space-between;
      }

      main {
        padding: 2.5rem 1rem 3rem;
      }

      .team-grid {
        grid-template-columns: 1fr;
      }

      section + section {
        margin-top: 3.5rem;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      *,
      *::before,
      *::after {
        scroll-behavior: auto !important;
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
      }
    }
  </style>
</head>
<body>
  <header class="site-header">
    <div class="header-inner">
      <div class="brand">
        <h1>The Review Queue</h1>
        <p class="tagline">Five computer science students, a healthy respect for code review, and exactly zero trust in a suspiciously confident bug.</p>
      </div>
      <div class="header-tools">
        <nav class="site-nav" aria-label="Main navigation">
          <a href="#team">Meet the team</a>
          <a href="#future-of-se">The future</a>
        </nav>
        <button id="theme-toggle" type="button" aria-label="Switch to night mode">☾</button>
      </div>
    </div>
  </header>

  <main>
    <section id="team" aria-labelledby="team-title">
      <p class="eyebrow">People before pull requests</p>
      <h2 id="team-title">Meet the team</h2>
      <p class="section-intro">We’re five first-semester M.Sc. Computer Science students with different corners of software engineering on our minds. Our shared debugging strategy: understand the problem, check the output, and maybe reorganize a terminal first.</p>

      <div class="team-grid">
        <article class="member-card">
          <img src="{{image:Dhruv.png}}" alt="Photo of Dhruv">
          <h3>Dhruv Savani</h3>
          <p class="study">M.Sc. Computer Science, 1st semester</p>
          <p class="bio">Dhruv is in the first semester of an M.Sc. in Computer Science and is interested in backend development, cloud infrastructure, and open-source tools. He finds AI assistants useful for boilerplate, refactoring, and explaining unfamiliar code, but knows they can make confident mistakes; he treats them as fast junior colleagues whose suggestions need careful review. Before a coding session, Dhruv reorganizes his terminal setup—a ritual that happens before the coding ritual.</p>
          <p class="fun-fact"><em>Fun fact: He can’t start a coding session without first reorganizing his terminal setup.</em></p>
          <p class="hot-take">🔥 AI won’t replace developers, but developers who ignore it will fall behind those who use it well.</p>
        </article>

        <article class="member-card">
          <img src="{{image:harshil.jpg}}" alt="Photo of Harshil">
          <h3>Harshil Zadafiya</h3>
          <p class="study">M.Sc. Computer Science, 1st semester</p>
          <p class="bio">Harshil is a first-semester M.Sc. Computer Science student interested in cybersecurity, DevOps, and automation. He sees AI speeding up scripting, log analysis, and configuration work, while also noting that generated code can contain insecure patterns or outdated dependencies without warning. For Harshil, security review and testing still matter regardless of who—or what—wrote the code. He automates small daily tasks even when doing them by hand would be quicker, because apparently the task is not complete until the task itself is automated.</p>
          <p class="fun-fact"><em>Fun fact: He automates small daily tasks even when doing them by hand would be quicker.</em></p>
          <p class="hot-take">🔥 Every line of AI-generated code is a security review waiting to happen.</p>
        </article>

        <article class="member-card">
          <img src="{{image:Jevin.png}}" alt="Photo of Jevin">
          <h3>Jevin Vaghasiya</h3>
          <p class="study">M.Sc. Computer Science, 1st semester</p>
          <p class="bio">Jevin is in the first semester of an M.Sc. in Computer Science and is interested in machine learning, mobile app development, and competitive programming. He uses AI tools to learn faster by asking for algorithm explanations and alternative solutions, but sees a risk when beginners skip the struggle that builds problem-solving skills. His preferred workflow is to try first, then use AI to check and improve the work. He learns new programming concepts best by explaining them aloud to a rubber duck, which is a very patient study partner.</p>
          <p class="fun-fact"><em>Fun fact: He learns new programming concepts best by explaining them out loud to a rubber duck.</em></p>
          <p class="hot-take">🔥 Code is getting cheap; knowing what to build and why is the skill that stays expensive.</p>
        </article>

        <article class="member-card">
          <img src="{{image:Pooja.png}}" alt="Photo of Pooja">
          <h3>Pooja Garg</h3>
          <p class="study">M.Sc. Computer Science, 1st semester</p>
          <p class="bio">Pooja is a first-semester M.Sc. Computer Science student interested in data science, user experience, and software testing. She finds AI useful for writing tests, summarizing data, and exploring ideas quickly, while stressing that its output depends on the question and data—and can sound right while being wrong. She prefers to validate results against real data and tests. Pooja reads error messages for fun, and finds that they usually tell her more than the documentation. The errors have, presumably, stopped being nervous about it.</p>
          <p class="fun-fact"><em>Fun fact: She reads error messages for fun, and they usually tell her more than the documentation.</em></p>
          <p class="hot-take">🔥 AI writes the code fast; tests decide whether anyone should trust it.</p>
        </article>

        <article class="member-card">
          <img src="{{image:Yasik.png}}" alt="Photo of Yashik">
          <h3>Yashik Khunt</h3>
          <p class="study">M.Sc. Computer Science, 1st semester</p>
          <p class="bio">Yashik is in the first semester of an M.Sc. in Computer Science and is interested in web development, UI design, and data visualization. He finds AI good at generating UI components and quick prototypes, but believes design judgment, accessibility, and understanding users still need a human. Used blindly, AI can also produce code nobody on the team fully understands. Yashik once spent a whole weekend hunting a bug that turned out to be a single missing semicolon—a tiny character with a truly outsized weekend plan.</p>
          <p class="fun-fact"><em>Fun fact: He once spent a whole weekend hunting a bug that turned out to be a single missing semicolon.</em></p>
          <p class="hot-take">🔥 Prompting is the new Stack Overflow: useful until you stop understanding the answer.</p>
        </article>
      </div>
    </section>

    <section id="future-of-se" aria-labelledby="future-title">
      <p class="eyebrow">Less typing, more thinking</p>
      <h2 id="future-title">The Future of Software Engineering</h2>
      <p class="future-intro">Across the team’s perspectives, one thing is clear: faster code does not make careful engineering optional. Here’s where those views meet—and where a useful debate remains.</p>

      <div class="future-panel">
        <h3>Shared throughlines</h3>
        <ul class="shared-points">
          <li>AI already helps with routine work, explanations, prototypes, tests, and scripting—but its output still needs human review.</li>
          <li>Verification matters: security checks, real data, tests, and reliability keep plausible-looking mistakes from shipping.</li>
          <li>Human judgment remains important for defining the problem, understanding users, and deciding what is worth building.</li>
          <li>Understanding the code matters even when an AI tool helped produce it; speed is not a substitute for comprehension.</li>
        </ul>

        <p class="outlook">
          <strong>Our 5–10 year outlook</strong>
          We expect more code to be generated and more pipelines to automate building, testing, and deployment. Engineers may spend less time typing and more time designing systems, setting requirements and guardrails, guiding AI agents, and reviewing outcomes. That makes architecture, reliability, security, compliance, testing, product thinking, and maintainability increasingly important. Prototypes may arrive in hours and small tools may be built by non-programmers, while deciding what deserves to exist—and whether it works safely—remains substantial engineering work.
        </p>

        <div class="tension">
          <h3>A live tension: accelerate or learn the hard way?</h3>
          <p><strong>One side:</strong> AI can accelerate coding and learning by handling boilerplate, explaining algorithms, and suggesting alternatives.</p>
          <p><strong>The other:</strong> relying on generated answers too early can skip the problem-solving struggle that builds skill, or leave a team with code it does not understand. The practical middle ground in these profiles is to try, inspect, and verify—not to outsource understanding.</p>
        </div>
      </div>
    </section>
  </main>

  <footer>
    <p>Built by an agent, supervised by humans. 2026 · The Review Queue</p>
  </footer>

  <script>
    (function () {
      const button = document.getElementById("theme-toggle");
      const root = document.documentElement;

      function updateButton(theme) {
        const switchingTo = theme === "dark" ? "light" : "dark";
        button.setAttribute("aria-label", "Switch to " + (switchingTo === "dark" ? "night" : "day") + " mode");
        button.textContent = theme === "dark" ? "☀" : "☾";
      }

      updateButton(root.getAttribute("data-theme"));

      button.addEventListener("click", function () {
        const nextTheme = root.getAttribute("data-theme") === "dark" ? "light" : "dark";
        root.setAttribute("data-theme", nextTheme);
        updateButton(nextTheme);
        try {
          localStorage.setItem("upb-theme", nextTheme);
        } catch (error) {
          // Theme still works for this visit when storage is unavailable.
        }
      });
    }());
  </script>
</body>
</html>
```

